(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin(x*0.035-t*0.5)*8 + Math.cos(y*0.028+t*0.45)*6;
  const w2y = Math.cos(y*0.032+t*0.55)*8 + Math.sin(x*0.025-t*0.4)*6;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.7],
    [80+Math.sin(t*0.65+3)*70, 40+Math.cos(t*0.75)*50, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.45+1)*60, 200+Math.sin(t*0.85+2)*55, 0.055, 2.8, 1.3]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f - t*sp)*w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5)*w;
    cS += Math.sin(d*f*1.3 - t*sp*0.4 + 3.0)*w*0.5;
  }
  const tw = 6.75;
  const act=aS/tw, inh=iS/tw, cor=cS/tw;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.07+sy*0.05-t*1.8)*0.15;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    + Math.sin(dist*0.08-ang*5+t*0.8)*0.2;
  const turb = Math.sin(sx*0.09+t*0.7)*Math.cos(sy*0.08-t*0.6)*0.25
    + Math.sin((sx*0.12-sy*0.1)+t*1.5)*0.15;
  const reaction = Math.tanh((act - inh*0.6 + bg*0.25 + spiral + cor*0.4 + turb)*2.0);
  const lap = Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5
    + Math.sin(sx*0.2-sy*0.18+t*1.3)*0.3 + Math.cos((sx-sy)*0.08+t*0.9)*0.2;
  const cell = Math.tanh(lap*1.5)*0.3;
  const detail = Math.sin(sx*0.3+t*2)*Math.sin(sy*0.25-t*1.8)*0.08*reaction;
  const blend = reaction*0.65 + cell*0.25 + detail, v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[12,42,88],[18,78,118],[24,125,128],
    [160,175,80],[210,185,60],[220,140,55],[190,85,60],
    [140,45,65],[70,22,55],[30,14,48],[6,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge = Math.abs(reaction)>0.65?1.0+Math.abs(reaction)*0.2:1.0;
  const glow = reaction>0.8?0.15:0;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*255))|0,
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*200))|0,
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*120))|0
  ];
}
